-- 3. Cross-agent reasoning audit ---------------------------------------------
-- Result of a deterministic, no-AI-call consistency pass across every
-- agent's output for a case, run once after the pipeline's normal stage
-- loop finishes (see runCrossAgentValidator in
-- src/lib/intelligence/cross-agent-validator.server.ts). Advisory only —
-- never blocks or retries pipeline stages; it flags disagreements for
-- attorney review rather than silently picking a winner.
CREATE TABLE IF NOT EXISTS public.cross_agent_audit (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  report_version integer,
  checks jsonb NOT NULL DEFAULT '[]'::jsonb,
  conflicts jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'ok' CHECK (status IN ('ok', 'warnings', 'conflicts')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS cross_agent_audit_case_idx ON public.cross_agent_audit (case_id, created_at DESC);

GRANT SELECT ON public.cross_agent_audit TO authenticated;
GRANT ALL ON public.cross_agent_audit TO service_role;

ALTER TABLE public.cross_agent_audit ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can view their own case audits" ON public.cross_agent_audit;
CREATE POLICY "Users can view their own case audits"
  ON public.cross_agent_audit
  FOR SELECT
  TO authenticated
  USING (auth.uid() = user_id);

COMMENT ON TABLE public.cross_agent_audit IS
  'One row per cross-agent validation pass. checks = every check performed (pass/fail + detail); conflicts = disagreements the validator could not resolve deterministically, surfaced for attorney review rather than silently resolved.';


-- MIGRATION: 20260801054557_299109c0-f53b-49f4-a8af-8ed5066f7bee.sql
-- 1. Resolve pre-existing duplicate active rows so the unique index can be built.
WITH ranked AS (
  SELECT id,
         row_number() OVER (
           PARTITION BY case_id, engine
           ORDER BY created_at DESC, id DESC
         ) AS rn
    FROM public.pipeline_engine_runs
   WHERE status IN ('queued', 'running')
)
UPDATE public.pipeline_engine_runs r
   SET status = 'failed',
       error = COALESCE(r.error, 'superseded_duplicate_active_run'),
       ended_at = COALESCE(r.ended_at, now()),
       meta = r.meta || jsonb_build_object('superseded_by_duplicate_guard', true),
       updated_at = now()
  FROM ranked
 WHERE ranked.id = r.id
   AND ranked.rn > 1;

-- 2. Atomic guard: at most one active (queued/running) run per (case_id, engine).
CREATE UNIQUE INDEX IF NOT EXISTS uniq_pipeline_engine_runs_active
  ON public.pipeline_engine_runs (case_id, engine)
  WHERE status IN ('queued', 'running');

-- 3. Atomic claim helper: returns the run id, or NULL when another worker holds it.
CREATE OR REPLACE FUNCTION public.claim_engine_run(
  _case_id uuid,
  _user_id uuid,
  _engine text,
  _meta jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _id uuid;
BEGIN
  INSERT INTO public.pipeline_engine_runs (case_id, user_id, engine, status, started_at, meta)
  VALUES (_case_id, _user_id, _engine, 'running', now(), _meta)
  RETURNING id INTO _id;
  RETURN _id;
EXCEPTION
  WHEN unique_violation THEN
    RETURN NULL;
END;
$$;

GRANT EXECUTE ON FUNCTION public.claim_engine_run(uuid, uuid, text, jsonb) TO authenticated, service_role;

-- MIGRATION: 20260804120000_add_stall_auto_retry_count.sql
-- Bounded auto-retry counter for the stall watchdog (pipeline-stall.server.ts).
-- Previously every stalled case was force-failed and left for a human to
-- click "Resume" -- the exact "stuck in generation" symptom this column
-- exists to fix. Bounded (not unconditional) so a case whose stall cause is
-- deterministic (e.g. a stage that always hangs) doesn't retry forever and
-- burn AI spend -- after MAX_AUTO_STALL_RETRIES it falls back to the
-- existing manual-resume path.
ALTER TABLE public.cases
  ADD COLUMN IF NOT EXISTS stall_auto_retry_count integer NOT NULL DEFAULT 0;


