-- self-scope guard so signed-in users cannot probe other users' firm relationships
CREATE OR REPLACE FUNCTION public.same_firm(_a uuid, _b uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (auth.uid() IS NULL OR _a = auth.uid() OR _b = auth.uid())
     AND EXISTS (
    SELECT 1
    FROM public.user_settings ua
    JOIN public.user_settings ub ON ub.user_id = _b AND ua.firm_id = ub.firm_id
    WHERE ua.user_id = _a AND ua.firm_id IS NOT NULL
  );
$$;

-- MIGRATION: 20260806223907_77d462a0-61a8-45f9-a763-2899f5362c57.sql
GRANT EXECUTE ON FUNCTION public.admin_grant_beta_access(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_list_users_with_subscriptions() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_list_pending_beta_invites() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_list_firms_with_seats() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_get_user_id_by_email(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_factory_reset_case_data(boolean, boolean, boolean, uuid) TO authenticated;

-- MIGRATION: 20260807010000_support_messages_thread_system.sql
-- Unified in-app support/message system. Replaces the one-way user_feedback
-- inbox (submit -> admin sees it -> admin can only leave a PRIVATE internal
-- admin_note) with a real two-way thread: the sender can see the admin's
-- reply inside the app, and the admin can see when the sender writes back —
-- both surfaced via server-tracked unread flags, not a client-only dismiss
-- list, so "you have a reply" is correct across devices/sessions.
--
-- "Comentarios" (the floating feedback button) and "Help & Support" both
-- funnel into this same system as different categories on one thread type,
-- per product decision — one inbox for the admin to triage, not two.

CREATE TABLE IF NOT EXISTS public.support_threads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  email text,
  -- 'support' = opened from the Help & Support entry point; the rest match
  -- the categories the existing Comentarios button already offers.
  category text NOT NULL DEFAULT 'general'
    CHECK (category IN ('support', 'bug', 'wrong_result', 'missing_feature', 'usability', 'legal_accuracy', 'general')),
  severity text NOT NULL DEFAULT 'normal' CHECK (severity IN ('low', 'normal', 'high', 'blocking')),
  page_path text,
  case_id uuid,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'resolved')),
  -- Whose turn it is to read the latest message. Flipped by the server
  -- function that appends a message, and cleared by the server function
  -- that opens a thread for reading (see support.functions.ts) — never by
  -- the client directly, so this can't be spoofed into a false "read".
  unread_by_admin boolean NOT NULL DEFAULT true,
  unread_by_user boolean NOT NULL DEFAULT false,
  last_message_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS support_threads_user_idx ON public.support_threads (user_id, last_message_at DESC);
CREATE INDEX IF NOT EXISTS support_threads_admin_unread_idx ON public.support_threads (unread_by_admin, last_message_at DESC);

CREATE TABLE IF NOT EXISTS public.support_messages (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  thread_id uuid NOT NULL REFERENCES public.support_threads(id) ON DELETE CASCADE,
  sender text NOT NULL CHECK (sender IN ('user', 'admin')),
  sender_user_id uuid REFERENCES auth.users(id),
  body text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS support_messages_thread_idx ON public.support_messages (thread_id, created_at ASC);

GRANT SELECT, INSERT ON public.support_threads TO authenticated;
GRANT SELECT, INSERT ON public.support_messages TO authenticated;
GRANT ALL ON public.support_threads TO service_role;
GRANT ALL ON public.support_messages TO service_role;

ALTER TABLE public.support_threads ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.support_messages ENABLE ROW LEVEL SECURITY;

-- A user opens their own thread by inserting it directly (first message is
-- written right after in the same request — see submitSupportMessage).
DROP POLICY IF EXISTS "support_threads_insert_own" ON public.support_threads;
CREATE POLICY "support_threads_insert_own" ON public.support_threads
  FOR INSERT TO authenticated
  WITH CHECK (auth.uid() = user_id);

DROP POLICY IF EXISTS "support_threads_select_own_or_admin" ON public.support_threads;
CREATE POLICY "support_threads_select_own_or_admin" ON public.support_threads
  FOR SELECT TO authenticated
  USING (auth.uid() = user_id OR public.is_admin_tier(auth.uid()));

-- Every other write to support_threads (unread flags, status, last_message_at)
-- goes through the service-role client from an admin- or ownership-checked
-- server function — same pattern user_feedback already established for
-- adminUpdateFeedback — so there is no general-purpose UPDATE policy here.

-- A user may append a message to their OWN thread, and only as sender='user'
-- attributed to themselves — an admin reply is never insertable by a
-- non-admin client because that path always goes through the service-role
-- client after an explicit is_admin_tier check in adminReplyToThread.
DROP POLICY IF EXISTS "support_messages_insert_own_thread" ON public.support_messages;
CREATE POLICY "support_messages_insert_own_thread" ON public.support_messages
  FOR INSERT TO authenticated
  WITH CHECK (
    sender = 'user'
    AND sender_user_id = auth.uid()
    AND EXISTS (SELECT 1 FROM public.support_threads t WHERE t.id = thread_id AND t.user_id = auth.uid())
  );

DROP POLICY IF EXISTS "support_messages_select_own_or_admin" ON public.support_messages;
CREATE POLICY "support_messages_select_own_or_admin" ON public.support_messages
  FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.support_threads t
      WHERE t.id = thread_id AND (t.user_id = auth.uid() OR public.is_admin_tier(auth.uid()))
    )
  );

DROP TRIGGER IF EXISTS trg_support_threads_updated ON public.support_threads;
CREATE TRIGGER trg_support_threads_updated BEFORE UPDATE ON public.support_threads
  FOR EACH ROW EXECUTE FUNCTION public.tg_set_updated_at();


-- MIGRATION: 20260807120000_case_reminders_and_worker.sql
-- Reminders for calendar events and task deadlines. Subscribers can enable a
-- reminder on any hearing/event or task deadline, choose how far in advance
-- it fires, and pick delivery channels (in-app/browser notification and/or
-- email to their account address). A background worker (pg_cron, same
-- pattern as nyrava-pipeline-worker) fires due reminders on a schedule.

ALTER TABLE public.case_events
  ADD COLUMN IF NOT EXISTS reminder_enabled BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS reminder_lead_minutes INTEGER NOT NULL DEFAULT 60,
  ADD COLUMN IF NOT EXISTS reminder_channels TEXT[] NOT NULL DEFAULT ARRAY['browser']::TEXT[],
  ADD COLUMN IF NOT EXISTS reminder_fired_at TIMESTAMPTZ;

ALTER TABLE public.case_tasks
  ADD COLUMN IF NOT EXISTS reminder_enabled BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS reminder_lead_minutes INTEGER NOT NULL DEFAULT 1440,
  ADD COLUMN IF NOT EXISTS reminder_channels TEXT[] NOT NULL DEFAULT ARRAY['browser']::TEXT[],
  ADD COLUMN IF NOT EXISTS reminder_fired_at TIMESTAMPTZ;

-- Guard against garbage channel values slipping in outside the app layer.
ALTER TABLE public.case_events DROP CONSTRAINT IF EXISTS case_events_reminder_channels_check;
ALTER TABLE public.case_events
  ADD CONSTRAINT case_events_reminder_channels_check
  CHECK (reminder_channels <@ ARRAY['browser','email']::TEXT[]);

ALTER TABLE public.case_tasks DROP CONSTRAINT IF EXISTS case_tasks_reminder_channels_check;
ALTER TABLE public.case_tasks
  ADD CONSTRAINT case_tasks_reminder_channels_check
  CHECK (reminder_channels <@ ARRAY['browser','email']::TEXT[]);

CREATE INDEX IF NOT EXISTS idx_case_events_reminder_due
  ON public.case_events (scheduled_at)
  WHERE reminder_enabled AND reminder_fired_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_case_tasks_reminder_due
  ON public.case_tasks (due_date)
  WHERE reminder_enabled AND reminder_fired_at IS NULL;

-- Worker secret + cron job, following the exact pattern used for
-- nyrava-pipeline-worker (worker_secrets table, x-worker-secret header,
-- service-role-only access).
INSERT INTO public.worker_secrets (name, secret)
VALUES ('reminders_worker', encode(gen_random_bytes(32), 'hex'))
ON CONFLICT (name) DO NOTHING;

DO $$
DECLARE
  _secret TEXT;
BEGIN
  SELECT secret INTO _secret FROM public.worker_secrets WHERE name = 'reminders_worker';
  PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'nyrava-reminders-worker';
  PERFORM cron.schedule(
    'nyrava-reminders-worker',
    '*/5 * * * *',
    format($cmd$
      SELECT net.http_post(
        url := 'https://mexico.nyrava.com/api/public/hooks/reminders-worker',
        headers := %L::jsonb,
        body := '{}'::jsonb
      );
    $cmd$, jsonb_build_object('Content-Type','application/json','x-worker-secret', _secret)::text)
  );
END $$;


-- MIGRATION: 20260808201119_finding_judicial_attribution.sql
-- ============================================================================
-- Judicial-hierarchy attribution on findings.
--
-- Bug: a finding extracted from a multi-instance resolution (e.g. an amparo
-- directo en revisión reviewing a Tribunal Colegiado sentencia) carried no
-- record of who asserted it or whether the highest instance in the case
-- adopted it. A Tribunal Colegiado holding the SCJN's Pleno expressly
-- revoked could therefore render in the Executive Dashboard's Hallazgos
-- Principales indistinguishably from an actual adopted SCJN holding. See
-- src/lib/intelligence/judicial-hierarchy.ts for the enforcement layer that
-- consumes these columns.
--
-- Additive by construction: nullable, no default, no backfill. Every
-- existing finding (and every finding from a materia that never runs the
-- judicial-hierarchy attribution prompt — the overwhelming majority of
-- cases) keeps working unchanged with all three columns NULL, which
-- judicial-hierarchy.ts treats as "not attributed" and passes through
-- every filter untouched.
-- ============================================================================

ALTER TABLE public.case_findings
  ADD COLUMN IF NOT EXISTS speaker_role text,
  ADD COLUMN IF NOT EXISTS proposition_type text,
  ADD COLUMN IF NOT EXISTS adoption_status text;

ALTER TABLE public.case_findings
  ADD CONSTRAINT case_findings_speaker_role_check
    CHECK (speaker_role IS NULL OR speaker_role IN ('quejoso', 'autoridad', 'tribunal_colegiado', 'tribunal_local', 'scjn'));

ALTER TABLE public.case_findings
  ADD CONSTRAINT case_findings_proposition_type_check
    CHECK (proposition_type IS NULL OR proposition_type IN ('argument', 'holding', 'rejected_holding', 'procedural_fact', 'evidence', 'issue'));

ALTER TABLE public.case_findings
  ADD CONSTRAINT case_findings_adoption_status_check
    CHECK (adoption_status IS NULL OR adoption_status IN ('adopted', 'rejected', 'unresolved', 'historical'));

COMMENT ON COLUMN public.case_findings.speaker_role IS
  'Who asserted this proposition in the source judicial resolution: quejoso|autoridad|tribunal_colegiado|tribunal_local|scjn. NULL when the extraction pass did not run judicial-hierarchy attribution (most non-precedent-review findings). Distinct from affected_party, which says who a finding BENEFITS, not who stated it.';
COMMENT ON COLUMN public.case_findings.proposition_type IS
  'argument|holding|rejected_holding|procedural_fact|evidence|issue. rejected_holding marks a lower instance''s ruling a higher instance expressly overturned or superseded — this and adoption_status=rejected are the two signals that keep a finding out of the Executive Dashboard.';
COMMENT ON COLUMN public.case_findings.adoption_status IS
  'adopted|rejected|unresolved|historical — whether the highest instance present in the case adopted this proposition. Drives Executive Dashboard / Hallazgos Principales / Resumen Ejecutivo / Puntajes / Recomendaciones eligibility; see src/lib/intelligence/judicial-hierarchy.ts.';


-- MIGRATION: 20260809041757_case_analysis_mode.sql
-- ============================================================================
-- Case Analysis Mode — orchestration axis, orthogonal to case_type (materia)
-- and analysis_mode (evidence strictness). Tells the existing engines what
-- OBJECTIVE they are pursuing: standard case preparation ("ongoing", the
-- default — every existing case keeps this value and therefore keeps its
-- exact current behavior), or one of three retrospective forensic-audit
-- postures for a concluded case. See
-- src/lib/intelligence/case-analysis-mode.ts for the enforcement layer.
--
-- NOT NULL DEFAULT 'ongoing': every existing row gets 'ongoing' on migrate,
-- identical to today's behavior. Additive by construction.
-- ============================================================================

ALTER TABLE public.cases
  ADD COLUMN IF NOT EXISTS case_analysis_mode text NOT NULL DEFAULT 'ongoing';

ALTER TABLE public.cases
  ADD CONSTRAINT cases_case_analysis_mode_check
    CHECK (case_analysis_mode IN ('ongoing', 'concluded_audit', 'judgment_audit', 'appeal_routes'));

COMMENT ON COLUMN public.cases.case_analysis_mode IS
  'ongoing (default, case preparation) | concluded_audit (retrospective forensic audit) | judgment_audit (focused on the final resolution) | appeal_routes (focused on identifying legally supportable challenge routes). See src/lib/intelligence/case-analysis-mode.ts.';

-- ----------------------------------------------------------------------------
-- Completed-case finding classification — additive, nullable, no backfill.
-- Populated only by findings generated under a completed-case analysis mode
-- (the vast majority of findings, generated under "ongoing", leave this
-- NULL and are untouched — see normAuditClassification in findings.server.ts,
-- which follows the exact same additive pattern as speaker_role/
-- proposition_type/adoption_status from the judicial-hierarchy migration).
-- ----------------------------------------------------------------------------

ALTER TABLE public.case_findings
  ADD COLUMN IF NOT EXISTS audit_classification text;

ALTER TABLE public.case_findings
  ADD CONSTRAINT case_findings_audit_classification_check
    CHECK (
      audit_classification IS NULL OR audit_classification IN (
        'VERIFIED_FACT',
        'VERIFIED_COURT_HOLDING',
        'VERIFIED_LEGAL_RULE',
        'SUPPORTED_INFERENCE',
        'POTENTIAL_ISSUE',
        'EVIDENCE_GAP',
        'NOT_FOUND'
      )
    );

COMMENT ON COLUMN public.case_findings.audit_classification IS
  'VERIFIED_FACT|VERIFIED_COURT_HOLDING|VERIFIED_LEGAL_RULE|SUPPORTED_INFERENCE|POTENTIAL_ISSUE|EVIDENCE_GAP|NOT_FOUND — strict finding classification used by completed-case analysis modes. NULL for findings generated outside those modes. See src/lib/intelligence/case-analysis-mode.ts.';


-- MIGRATION: 20260809135402_completed_case_audit.sql
-- ============================================================================
-- Completed Case Audit / Outcome Assessment — additive, brand-new table.
--
-- Explicitly NOT a change to case_findings, cases, reports, or any existing
-- pipeline table: a "final quality-control attorney review" layer that
-- reads the EXISTING completed-case results (case_findings, case_scores,
-- reports) and writes its own independent judgment here, never mutating
-- what it reviewed. See src/lib/intelligence/completed-case-audit.server.ts.
--
-- One row per audit run (a case rerun under a completed-case analysis mode
-- gets a fresh row, not an overwrite, so the audit history is never lost).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.case_outcome_assessments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  case_analysis_mode text NOT NULL,

  overall_position text NOT NULL CHECK (overall_position IN ('FAVORABLE', 'UNFAVORABLE', 'MIXED')),
  favorable_pct integer NOT NULL CHECK (favorable_pct BETWEEN 0 AND 100),
  unfavorable_pct integer NOT NULL CHECK (unfavorable_pct BETWEEN 0 AND 100),
  confidence text NOT NULL CHECK (confidence IN ('LOW', 'MODERATE', 'HIGH')),

  principal_strength text,
  principal_weakness text,
  biggest_risk text,
  most_important_missing_evidence text,

  -- Structured breakdowns — see completed-case-audit.server.ts for the
  -- exact shape written into each. Kept as jsonb (not new columns per
  -- field) since this is genuinely variable-shape narrative content, not
  -- queryable scalar data, and case_findings has already taught this
  -- codebase twice what happens when every new field becomes its own
  -- column on a hot-path table — this table isn't one, so jsonb here is a
  -- deliberate choice, not corner-cutting.
  both_sides jsonb NOT NULL DEFAULT '{}'::jsonb,
  factors jsonb NOT NULL DEFAULT '{}'::jsonb,
  what_could_change jsonb NOT NULL DEFAULT '{}'::jsonb,

  -- Per-finding review outcome: [{ finding_id, status, note }], status one
  -- of VERIFIED|CORRECTED|UNVERIFIED|CONTRADICTED|MISSING_EVIDENCE.
  finding_reviews jsonb NOT NULL DEFAULT '[]'::jsonb,

  -- Statutory-citation re-verification results (verifyStatutoryCitation()
  -- output per citation found in the existing analysis) — real, deterministic
  -- checks against public.legal_authorities/legal_articles, not LLM claims.
  citation_reviews jsonb NOT NULL DEFAULT '[]'::jsonb,

  raw_model_output jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.case_outcome_assessments TO authenticated;
GRANT ALL ON public.case_outcome_assessments TO service_role;
ALTER TABLE public.case_outcome_assessments ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS case_outcome_assessments_owner_select ON public.case_outcome_assessments;
CREATE POLICY case_outcome_assessments_owner_select ON public.case_outcome_assessments
  FOR SELECT USING (user_id = auth.uid() AND private.owns_case(case_id));

CREATE INDEX IF NOT EXISTS case_outcome_assessments_case_idx
  ON public.case_outcome_assessments(case_id, created_at DESC);

COMMENT ON TABLE public.case_outcome_assessments IS
  'Completed Case Audit / Outcome Assessment — a final review layer over EXISTING completed-case findings/scores/report. Never regenerates or reprocesses documents; see src/lib/intelligence/completed-case-audit.server.ts.';


-- MIGRATION: 20260809140747_completed_case_audit_outcome_status.sql
-- ============================================================================
-- Zero-hallucination hardening for the Completed Case Audit — additive only.
--
-- Adds an explicit, queryable state distinguishing "we produced a real
-- probability estimate" from "the record does not support one" — see
-- src/lib/intelligence/completed-case-audit.server.ts. Before this, the
-- engine always forced favorable_pct/unfavorable_pct to sum to 100 even
-- when the underlying evidence was too thin to support any meaningful
-- number. NOT NULL DEFAULT 'ESTIMATED' preserves every existing row's
-- current meaning unchanged.
-- ============================================================================

ALTER TABLE public.case_outcome_assessments
  ADD COLUMN IF NOT EXISTS outcome_status text NOT NULL DEFAULT 'ESTIMATED';

ALTER TABLE public.case_outcome_assessments
  ADD CONSTRAINT case_outcome_assessments_outcome_status_check
    CHECK (outcome_status IN ('ESTIMATED', 'INSUFFICIENT_DATA'));

COMMENT ON COLUMN public.case_outcome_assessments.outcome_status IS
  'ESTIMATED: favorable_pct/unfavorable_pct/confidence reflect a real evidence-based assessment. INSUFFICIENT_DATA: the record does not support a meaningful probability — favorable_pct/unfavorable_pct/confidence are placeholders (0/0/LOW) and must not be displayed as a real estimate. See completed-case-audit.server.ts.';

-- Also additive: a "no material error identified" is itself a valid,
-- meaningful audit result (spec rule 6) — distinct from "the audit found
-- nothing" or "the audit failed to run." Recorded explicitly so the UI can
-- render it as a positive result, not an empty state.
ALTER TABLE public.case_outcome_assessments
  ADD COLUMN IF NOT EXISTS no_material_error_identified boolean NOT NULL DEFAULT false;


-- MIGRATION: 20260809143021_case_classification_evidence.sql
-- ============================================================================
-- Automatic Case Classification — source-grounded, evidence-gated.
--
-- Additive only. Existing case_type/jurisdiction auto-detect
-- (mx-auto-detect.server.ts, mx-case-classifier.ts) always guessed and never
-- recorded WHY — this table is the evidence trail: which document, which
-- page, which exact quote justified each detected field, or that the
-- documents disagreed (CONFLICT) or didn't establish it (INSUFFICIENT_DATA).
-- See src/lib/intelligence/case-classification.server.ts.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.case_classification_evidence (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,

  field text NOT NULL CHECK (field IN (
    'case_type', 'proceeding_type', 'jurisdiction', 'matter',
    'procedural_stage', 'expediente_number', 'court', 'parties',
    'concluded_status'
  )),
  status text NOT NULL CHECK (status IN ('CONFIRMED', 'INSUFFICIENT_DATA', 'CONFLICT')),
  value text,
  confidence numeric,

  source_document_id uuid REFERENCES public.documents(id) ON DELETE SET NULL,
  source_page integer,
  source_quote text,

  -- Populated only when status = 'CONFLICT': every distinct value seen
  -- across documents, each with its own source — never silently picked.
  conflicting_values jsonb NOT NULL DEFAULT '[]'::jsonb,

  detected_at timestamptz NOT NULL DEFAULT now(),
  -- One row per (case, field) — a fresh detection run replaces the prior
  -- row for that field rather than accumulating history; see
  -- runCaseClassification()'s delete-then-insert.
  UNIQUE (case_id, field)
);

GRANT SELECT ON public.case_classification_evidence TO authenticated;
GRANT ALL ON public.case_classification_evidence TO service_role;
ALTER TABLE public.case_classification_evidence ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS case_classification_evidence_owner_select ON public.case_classification_evidence;
CREATE POLICY case_classification_evidence_owner_select ON public.case_classification_evidence
  FOR SELECT USING (user_id = auth.uid() AND private.owns_case(case_id));

CREATE INDEX IF NOT EXISTS case_classification_evidence_case_idx
  ON public.case_classification_evidence(case_id);

COMMENT ON TABLE public.case_classification_evidence IS
  'Evidence trail for automatic case classification (case type, jurisdiction, court, parties, expediente number, procedural stage, concluded status). Never guesses: CONFIRMED requires a located source quote, CONFLICT records every disagreeing source, INSUFFICIENT_DATA when the corpus does not establish the field. See case-classification.server.ts.';

-- ----------------------------------------------------------------------------
-- Provenance of the ACTIVE cases.case_type/jurisdiction values — additive,
-- nullable, no backfill. Lets a manual override be distinguished from a
-- source-confirmed value without joining the evidence table on every read.
-- ----------------------------------------------------------------------------
ALTER TABLE public.cases
  ADD COLUMN IF NOT EXISTS case_type_source text,
  ADD COLUMN IF NOT EXISTS case_type_verification_status text;

ALTER TABLE public.cases
  ADD CONSTRAINT cases_case_type_source_check
    CHECK (case_type_source IS NULL OR case_type_source IN (
      'source_confirmed', 'manual_override', 'manual_override_conflicting', 'heuristic', 'unresolved'
    ));

ALTER TABLE public.cases
  ADD CONSTRAINT cases_case_type_verification_status_check
    CHECK (case_type_verification_status IS NULL OR case_type_verification_status IN (
      'CONFIRMED', 'INSUFFICIENT_DATA', 'CONFLICT'
    ));

COMMENT ON COLUMN public.cases.case_type_source IS
  'Provenance of the current case_type value: source_confirmed (from case_classification_evidence) | manual_override (attorney-set, no conflicting source) | manual_override_conflicting (attorney-set, but disagrees with a CONFIRMED source classification — see case_classification_evidence) | heuristic (legacy keyword guess, pre-dates this table) | unresolved.';
COMMENT ON COLUMN public.cases.case_type_verification_status IS
  'CONFIRMED | INSUFFICIENT_DATA | CONFLICT — mirrors case_classification_evidence.status for the case_type field, denormalized for cheap UI reads.';


-- MIGRATION: 20260809150000_finding_supersession.sql
-- ============================================================================
-- Finding supersession — Talk to Case as a CASE-STATE UPDATE, not another
-- document.
--
-- Bug: a Talk-to-Case attorney clarification was ingested exactly like any
-- other uploaded evidence file, and the analyzers/agents that regenerate on
-- rerun only ever clear-and-replace their OWN module's findings
-- (clearFindingsByModule). A conclusion the clarification corrects (e.g.
-- "Interés jurídico o legítimo no identificado en el corpus") could
-- therefore keep sitting in case_findings unmarked, right next to a fresh
-- finding drawn from the clarification that says the opposite — the report
-- then read as an original report with new findings appended, not one
-- internally-consistent re-analysis. See
-- src/lib/intelligence/case-state-reconciliation.server.ts, which is what
-- actually decides supersession (an LLM call whose output is verified
-- against the clarification's own real text before being applied — the same
-- "never trust an unverified claim" discipline as every other gate in this
-- codebase) and writes these columns.
--
-- Additive by construction: nullable, no default, no backfill. Every
-- existing finding keeps working unchanged with both columns NULL, which
-- listFindings() (findings.server.ts) — the single choke point the report,
-- dashboard, and scoring all read through — treats as "still active."
-- Deliberately NOT a case_timeline_events-style superseded_by uuid FK: a
-- clarification can retire several findings at once with no single
-- replacing row, so the audit trail is a reason string, not a foreign key.
-- ============================================================================

ALTER TABLE public.case_findings
  ADD COLUMN IF NOT EXISTS superseded_at timestamptz,
  ADD COLUMN IF NOT EXISTS superseded_reason text;

CREATE INDEX IF NOT EXISTS case_findings_active_idx
  ON public.case_findings(case_id)
  WHERE superseded_at IS NULL;

COMMENT ON COLUMN public.case_findings.superseded_at IS
  'Set when a later, verified case-state update (a Talk-to-Case clarification, currently the only source) established that this finding no longer reflects the case record. NULL = still active. listFindings() excludes superseded rows by default — the row itself is NEVER deleted, preserving the audit trail.';
COMMENT ON COLUMN public.case_findings.superseded_reason IS
  'Human-readable explanation of why this finding was superseded and by what, including a verbatim quote from the superseding source. NULL whenever superseded_at is NULL.';


-- MIGRATION: 20260810130700_case_decision_reconstruction.sql
-- ============================================================================
-- Decision Reconstruction / Case Baseline — additive, brand-new table.
--
-- Phase 2/3 of the "Universal Completed Case Legal Audit Architecture Fix."
-- Unlike case_outcome_assessments (which reviews EXISTING case_findings/
-- case_scores/reports), this table stores an INDEPENDENT reconstruction of
-- what the case corpus itself establishes — matter identity, court,
-- jurisdiction, procedural posture, parties, procedural history, material
-- facts, issues presented, party arguments, evidence/factual findings,
-- applicable legal authorities, court reasoning, court holding, disposition/
-- remedy, unresolved issues, and cited precedent — built directly from the
-- documents, not derived from prior analysis output. See
-- src/lib/intelligence/decision-reconstruction.ts for the TypeScript shape
-- (CaseDecisionReconstruction) this table persists, and
-- src/lib/intelligence/decision-reconstruction-extractor.server.ts for the
-- extraction pass that populates it.
--
-- One row per reconstruction run (a re-run after a corpus change gets a
-- fresh row, not an overwrite, so reconstruction history is never lost —
-- same convention as case_outcome_assessments).
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.case_decision_reconstructions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  case_id uuid NOT NULL REFERENCES public.cases(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,

  -- The full CaseDecisionReconstruction object (every field already
  -- Sourced<T> — status + value + source_refs — at the application layer;
  -- stored whole here rather than exploded into columns, since almost every
  -- field is itself a variable-length array of Sourced entries).
  reconstruction jsonb NOT NULL,

  -- Denormalized top-level status flags for cheap filtering/monitoring
  -- without parsing the full jsonb blob — never the source of truth,
  -- `reconstruction` always is.
  matter_identity_status text,
  court_status text,
  disposition_remedy_status text,

  raw_model_output jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT ON public.case_decision_reconstructions TO authenticated;
GRANT ALL ON public.case_decision_reconstructions TO service_role;
ALTER TABLE public.case_decision_reconstructions ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS case_decision_reconstructions_owner_select ON public.case_decision_reconstructions;
CREATE POLICY case_decision_reconstructions_owner_select ON public.case_decision_reconstructions
  FOR SELECT USING (user_id = auth.uid() AND private.owns_case(case_id));

CREATE INDEX IF NOT EXISTS case_decision_reconstructions_case_idx
  ON public.case_decision_reconstructions(case_id, created_at DESC);

COMMENT ON TABLE public.case_decision_reconstructions IS
  'Decision Reconstruction / Case Baseline — an independent reconstruction of what the case corpus establishes, built directly from documents rather than derived from prior findings/scores. See src/lib/intelligence/decision-reconstruction-extractor.server.ts.';


