-- MIGRATION: 20260821000000_social_search_index_immutability.sql
-- Repair PostgreSQL 42P17 on the Social people full-text index.
-- array_to_string(text[], text) is not accepted directly in an index expression
-- on supported Supabase PostgreSQL versions. The fixed wrapper is deterministic
-- for text inputs and a fixed text-search configuration.

drop index if exists public.social_people_search_idx;

create or replace function public.social_people_search_document(
  p_legal_name text,
  p_preferred_name text,
  p_aliases text[]
) returns tsvector
language sql
immutable
parallel safe
set search_path = public
as $$
  select to_tsvector(
    'simple'::regconfig,
    coalesce(p_legal_name,'') || ' ' ||
    coalesce(p_preferred_name,'') || ' ' ||
    coalesce(array_to_string(p_aliases,' '),'')
  );
$$;

create index social_people_search_idx
on public.social_people using gin (
  public.social_people_search_document(legal_name,preferred_name,aliases)
);


-- MIGRATION: 20260821010000_social_organization_onboarding.sql
-- Atomic account-level law-firm/organization setup.
-- Replaces the browser-side multi-call flow so organization, ownership,
-- program configuration and Social authority either all save or all roll back.

create or replace function public.create_account_organization(
  p_name text,
  p_slug text,
  p_prefix text default 'NYR-SOC'
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_user uuid := auth.uid();
  v_org public.organizations%rowtype;
begin
  if v_user is null then
    raise exception 'Authentication required';
  end if;
  if length(btrim(coalesce(p_name,''))) < 2 then
    raise exception 'Organization name is required';
  end if;
  if p_slug !~ '^[a-z0-9][a-z0-9-]{2,79}$' then
    raise exception 'Organization slug is invalid';
  end if;
  if p_prefix !~ '^[A-Z0-9-]{2,20}$' then
    raise exception 'Social case prefix is invalid';
  end if;

  insert into public.organizations(name,slug,created_by,status)
  values(btrim(p_name),p_slug,v_user,'active')
  returning * into v_org;

  insert into public.org_memberships(org_id,user_id,role_in_org,status,invited_by)
  select v_org.id,v_user,'owner','active',v_user
  where not exists (
    select 1 from public.org_memberships
    where org_id=v_org.id and user_id=v_user and status='active'
  );

  insert into public.social_programs(
    org_id,name,name_es,name_en,code,case_prefix,active,settings,created_by
  ) values(
    v_org.id,'Atención Integral','Atención Integral','Comprehensive Care',
    'atencion-integral',p_prefix,true,'{}'::jsonb,v_user
  );

  insert into public.social_role_assignments(
    org_id,user_id,role,scope_type,scope_id,active,assigned_by
  ) values(
    v_org.id,v_user,'organization_owner','organization',null,true,v_user
  );

  return jsonb_build_object(
    'id',v_org.id,
    'name',v_org.name,
    'slug',v_org.slug,
    'status',v_org.status,
    'casePrefix',p_prefix
  );
exception
  when unique_violation then
    raise exception 'That organization name or identifier is already in use';
end;
$$;

revoke all on function public.create_account_organization(text,text,text) from public;
grant execute on function public.create_account_organization(text,text,text) to authenticated;


-- MIGRATION: 20260821020000_social_authorization_argument_order.sql
begin;

-- Correct Social authorization helper argument order and preserve tenant isolation.
-- Core organization helpers are defined as (user_id, organization_id). Earlier
-- Social migrations called them as (organization_id, user_id), denying valid access.

create or replace function public.social_is_platform_admin(p_user uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.user_roles ur
    where ur.user_id = p_user
      and ur.role::text in ('super_admin','platform_admin')
  );
$$;

create or replace function public.social_is_org_member(p_org uuid, p_user uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_org_member(p_user,p_org)
    or public.social_is_platform_admin(p_user);
$$;

create or replace function public.social_can_manage_org(p_org uuid, p_user uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.can_manage_org(p_user,p_org)
    or public.social_is_platform_admin(p_user);
$$;

create or replace function public.social_can_contribute_org(p_org uuid, p_user uuid default auth.uid())
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.can_contribute_org(p_user,p_org)
    or public.social_is_platform_admin(p_user);
$$;

revoke all on function public.social_is_platform_admin(uuid) from public;
revoke all on function public.social_is_org_member(uuid,uuid) from public;
revoke all on function public.social_can_manage_org(uuid,uuid) from public;
revoke all on function public.social_can_contribute_org(uuid,uuid) from public;
grant execute on function public.social_is_platform_admin(uuid) to authenticated, service_role;
grant execute on function public.social_is_org_member(uuid,uuid) to authenticated, service_role;
grant execute on function public.social_can_manage_org(uuid,uuid) to authenticated, service_role;
grant execute on function public.social_can_contribute_org(uuid,uuid) to authenticated, service_role;

